const BEATS={"a1s1":[[5,"A storm hits the King's ship; the crew fight to save it"],[13,"The boatswain tells the nobles their titles mean nothing to the sea"],[25,"Sebastian and Antonio curse the crew"],[34,"The ship splits; everyone prepares to drown"]],"a1s2":[[47,"Miranda begs her father to calm the storm"],[56,"Prospero finally tells Miranda who she is"],[68,"Antonio's betrayal: how Prospero lost Milan"],[82,"Cast adrift, saved by Gonzalo's kindness"],[94,"Ariel reports the storm: no one harmed"],[110,"Ariel asks for freedom; Prospero reminds him of Sycorax"],[137,"Caliban: \"This island's mine\""],[161,"Ariel's songs lead Ferdinand to Miranda"],[166,"Love at first sight"],[184,"Prospero calls Ferdinand a spy and charms his sword"]],"a2s1":[[204,"Gonzalo tries to cheer the grieving King"],[208,"Antonio and Sebastian mock Gonzalo"],[276,"Francisco thinks Ferdinand swam ashore"],[278,"Sebastian blames Alonso for the loss"],[293,"Gonzalo's ideal commonwealth"],[316,"Ariel's music puts the others to sleep"],[324,"Antonio tempts Sebastian to kill his brother"],[356,"Ariel wakes Gonzalo just in time"],[362,"The plotters invent a story about lions"]],"a2s2":[[375,"Caliban curses Prospero and hides from a 'spirit'"],[378,"Trinculo shelters under Caliban's cloak"],[380,"Drunken Stephano finds a 'four-legged monster'"],[393,"Stephano and Trinculo find each other alive"],[397,"Caliban worships Stephano as a god"],[417,"Caliban promises to serve his new master"],[423,"\"Freedom, high-day!\""]],"a3s1":[[428,"Ferdinand carries logs, happy to do it for Miranda"],[430,"Miranda offers to carry them for him"],[438,"Miranda tells him her name against her father's order"],[441,"They declare their love"],[447,"Miranda proposes; they promise to marry"],[454,"Prospero, watching, is delighted"]],"a3s2":[[458,"The drunken three: Stephano, Trinculo and Caliban"],[476,"Caliban asks Stephano to kill Prospero"],[478,"Invisible Ariel says \"Thou liest\"; Trinculo gets the blame"],[499,"The plan: seize his books, then kill him as he sleeps"],[513,"Ariel's music frightens Stephano and Trinculo"],[519,"Caliban: \"The isle is full of noises\""]],"a3s3":[[529,"The King's party, worn out, gives up hope"],[531,"Antonio and Sebastian plan to strike tonight"],[539,"Strange shapes bring in a banquet"],[551,"Ariel as a harpy accuses the \"three men of sin\""],[555,"Prospero praises Ariel"],[558,"Alonso runs off to drown himself"],[563,"Gonzalo sends the others after the desperate men"]],"a4s1":[[568,"Prospero gives Miranda to Ferdinand, with a warning"],[575,"Prospero calls up his spirits for a show"],[587,"The masque: Iris, Ceres and Juno bless the couple"],[603,"Nymphs and reapers dance"],[607,"Prospero remembers Caliban's plot and stops the show"],[610,"\"Our revels now are ended\""],[617,"Ariel led the plotters into a stinking pond"],[627,"Stephano and Trinculo fall for the fine clothes"],[658,"Spirit hounds chase the thieves"]],"a5s1":[[664,"Ariel says he would pity the prisoners"],[670,"Prospero chooses forgiveness over vengeance"],[673,"Prospero gives up his magic"],[685,"Prospero reveals himself as Duke of Milan"],[691,"He forgives his brother and takes back his dukedom"],[699,"Ferdinand and Miranda revealed playing chess"],[707,"Father and son reunited; Miranda's \"brave new world\""],[720,"The boatswain: the ship is safe"],[731,"Caliban and the drunk thieves are brought in"],[747,"Caliban: \"I'll be wise hereafter\""],[753,"Prospero invites all to hear his story; Ariel is freed"]],"a5s2":[[758,"Prospero asks the audience to set him free"]]};
